SELECT i.id AS instance_id, i.schedule_id, i.business_type, i.business_id, i.task_key, i.schedule_scope FROM iws_process_instance i WHERE i.id IN
#{instanceId}
ORDER BY i.id

SELECT i.id AS instance_id, e.id AS event_id, i.schedule_id, i.business_type, i.business_id, i.task_key, i.schedule_scope FROM iws_process_event e JOIN iws_process_instance i ON i.id = e.instance_id WHERE e.id IN
#{eventId}
ORDER BY e.id

